/** A car's methods: pyBYD's `BydCar`. `Car` (car.ts) completes it. */
export abstract class CarMethods {
  readonly #invoker: Invoker;
  /** Lock and unlock the doors. */
  readonly lock: LockFeature;
  /** Start, stop and schedule climate control. */
  readonly hvac: HvacFeature;
  /** Seat heating and ventilation. */
  readonly seat: SeatFeature;
  /** Steering wheel heating. */
  readonly steering: SteeringFeature;
  /** Battery heating. */
  readonly battery: BatteryFeature;
  /** Find the car, flash the lights. */
  readonly finder: FinderFeature;
  /** Close the windows or crack them open. */
  readonly windows: WindowsFeature;
  /** Open and close the trunk. */
  readonly trunk: TrunkFeature;

  /** @internal */
  protected constructor(invoker: Invoker) {
    this.#invoker = invoker;
    const features = (): CarFeatures => this.features;
    this.lock = new LockFeature(invoker, features);
    this.hvac = new HvacFeature(invoker, features);
    this.seat = new SeatFeature(invoker, features);
    this.steering = new SteeringFeature(invoker, features);
    this.battery = new BatteryFeature(invoker, features);
    this.finder = new FinderFeature(invoker, features);
    this.windows = new WindowsFeature(invoker, features);
    this.trunk = new TrunkFeature(invoker, features);
  }

  /** The current state with active projections laid over it, by section. */
  get state(): VehicleSnapshot {
    return this.#invoker.callSync("car.state", {}, ["struct", "VehicleSnapshot"]);
  }

  /** The car's capability flags. */
  get capabilities(): VehicleCapabilities {
    return this.#invoker.callSync("car.capabilities", {}, null);
  }

  /** Every feature's availability, and the climate scale. */
  get features(): CarFeatures {
    return this.#invoker.callSync("car.features", {}, ["struct", "CarFeatures"]);
  }

  /** Fetch realtime data and merge it; returns the data as fetched. */
  updateRealtime(): Promise<VehicleRealtimeData> {
    return this.#invoker.call("car.update_realtime", {}, ["struct", "VehicleRealtimeData"]);
  }

  /** Fetch the HVAC status and merge it. */
  updateHvac(): Promise<HvacStatus> {
    return this.#invoker.call("car.update_hvac", {}, ["struct", "HvacStatus"]);
  }

  /** Fetch the location and merge it. */
  updateGps(): Promise<GpsInfo> {
    return this.#invoker.call("car.update_gps", {}, ["struct", "GpsInfo"]);
  }

  /**
   * Fetch the charging state and the schedule in one call and merge both; returns the charging
   * state.
   */
  updateCharging(): Promise<ChargingStatus> {
    return this.#invoker.call("car.update_charging", {}, ["struct", "ChargingStatus"]);
  }

  /** Fetch energy consumption and merge it. */
  updateEnergy(): Promise<EnergyConsumption> {
    return this.#invoker.call("car.update_energy", {}, ["struct", "EnergyConsumption"]);
  }

  /** Start charging now and wait for the change to settle. */
  startCharging(): Promise<ChargeChangeResult> {
    return this.#invoker.call("car.start_charging", {}, null);
  }

  /** Always fails with `BydEndpointNotSupportedError`: the cloud cannot stop a charge. */
  stopCharging(): Promise<ChargeChangeResult> {
    return this.#invoker.call("car.stop_charging", {}, null);
  }

  /** The supported and active AC charging current limits. */
  getAcCurrentLimit(): Promise<AcCurrentLimit> {
    return this.#invoker.call("car.get_ac_current_limit", {}, null);
  }

  /**
   * Save a smart-charging schedule, wait for it to settle, then refresh the charging state.
   *
   * @param startChargeTime - When charging starts, `HH:MM`.
   *
   * @param endChargeTime - When charging ends, `HH:MM`, or `full`.
   *
   * @param chargeWay - `s` (single), `e` (every day) or weekday indices.
   */
  saveChargingSchedule(startChargeTime: string, endChargeTime: string, chargeWay: string, options: CarScheduleOptions = {}): Promise<ChargeChangeResult> {
    return this.#invoker.call(
      "car.save_charging_schedule",
      {
        start_charge_time: startChargeTime,
        end_charge_time: endChargeTime,
        charge_way: chargeWay,
        enabled: options.enabled,
      },
      null,
    );
  }

  /**
   * Merge a `vehicleInfo` push (its raw `respondData`), after any command in flight.
   *
   * @param data - The push's `respondData`.
   */
  handleMqttRealtime(data: JsonObject): void {
    this.#invoker.callSync("car.handle_mqtt_realtime", { data }, null);
  }

  /**
   * Merge a `smartCharge` push (its raw `respondData`) (live charging state only).
   *
   * @param data - The push's `respondData`.
   */
  handleMqttCharging(data: JsonObject): void {
    this.#invoker.callSync("car.handle_mqtt_charging", { data }, null);
  }

  /**
   * Merge a `energyConsumption` push (its raw `respondData`).
   *
   * @param data - The push's `respondData`.
   */
  handleMqttEnergy(data: JsonObject): void {
    this.#invoker.callSync("car.handle_mqtt_energy", { data }, null);
  }

  /** Release the car's resources (nothing yet; pyBYD's lifecycle hook). */
  close(): void {
    this.#invoker.callSync("car.close", {}, null);
  }
}
